const brand: unique symbol = Symbol("Capability");
export type Capability = { readonly [brand]: true };      // erased at runtime, documents intent

export class ReferenceMonitor {
  readonly #policy: PolicyStore;                          // #private: enforced by the runtime
  constructor(policy: PolicyStore) { this.#policy = policy; }

  check(subject: Subject, op: Operation): Capability | null {
    if (subject.principal === undefined) return null;      // fail closed
    return this.#policy.allows(subject.principal, op) ? { [brand]: true } : null;
  }
}
